package com.witchersbestiary.test;
import com.google.gson.*;import com.witchersbestiary.signs.*;import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.item.*;import net.minecraft.entity.*;import net.minecraft.entity.attribute.EntityAttributes;import net.minecraft.block.Blocks;import net.minecraft.util.math.*;import java.nio.file.*;import java.util.*;
public final class Stage21GNetworkServer implements ModInitializer {
 private Path dir;private int phase,ticks,sign;private long nonce=System.currentTimeMillis();private long[] sent=new long[2];private String[] names={"WBOne","WBTwo"};private LivingEntity[] mobs=new LivingEntity[2];private Map<String,Object> results=new LinkedHashMap<>();
 private void check(boolean ok,String why){if(!ok)throw new IllegalStateException(why);}
 private void write(String name,Object value)throws Exception{var p=dir.resolve(name);var t=p.resolveSibling(name+".tmp");Files.writeString(t,new Gson().toJson(value));Files.move(t,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private JsonObject read(String name)throws Exception{return JsonParser.parseString(Files.readString(dir.resolve(name))).getAsJsonObject();}
 private void command(int i,String action,Object...args)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);sent[i]=nonce;j.addProperty("action",action);for(int n=0;n<args.length;n+=2)j.addProperty(args[n].toString(),args[n+1].toString());write(names[i]+".command.json",j);}
 private boolean ack(int i)throws Exception{return Files.exists(dir.resolve(names[i]+".reply.json"))&&read(names[i]+".reply.json").get("nonce").getAsLong()==sent[i];}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.stage21gNetwork"))return;dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));phase=Files.exists(dir.resolve("signs-resume.json"))?100:0;ServerTickEvents.END_SERVER_TICK.register(s->{try{if(phase==999)return;if(++ticks>10000)throw new IllegalStateException("Signs native timeout "+phase);var a=s.getPlayerManager().getPlayer(names[0]);var b=s.getPlayerManager().getPlayer(names[1]);if(a==null||b==null)return;var players=List.of(a,b);var w=s.getOverworld();if(ticks%100==0)write("signs-heartbeat.json",Map.of("phase",phase,"sign",sign,"ticks",ticks));switch(phase){
 case 0->{for(int i=0;i<2;i++){var p=players.get(i);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.getInventory().clear();for(int x=-5;x<6;x++)for(int z=-5;z<8;z++){w.setBlockState(new BlockPos(i*24+x,128,z),Blocks.STONE.getDefaultState());for(int y=129;y<136;y++)w.setBlockState(new BlockPos(i*24+x,y,z),Blocks.AIR.getDefaultState());}p.teleport(w,i*24+.5,129,.5,0,0);for(var type:SignType.values())p.getInventory().setStack(type.ordinal(),new ItemStack(net.minecraft.registry.Registries.ITEM.get(net.minecraft.util.Identifier.of("witchersbestiary:sign_lesson_"+type.name().toLowerCase(Locale.ROOT)))));command(i,"signLearn");}phase=1;}
 case 1->{if(!ack(0)||!ack(1))return;check(SignManager.state(a).learned()==31&&SignManager.state(b).learned()==31,"Both real clients learned all signs independently using lesson items");results.put("native_survival_learning_both",true);phase=10;}
 case 10->{if(sign==5){phase=50;break;}for(int i=0;i<2;i++){var p=players.get(i);p.closeHandledScreen();p.teleport(w,i*24+.5,129,.5,0,0);var e=com.witchersbestiary.entity.ModEntities.GHOUL.create(w);e.refreshPositionAndAngles(i*24+.5,129,3.5,180,0);e.setPersistent();e.setAiDisabled(true);e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(200);e.setHealth(200);w.spawnEntity(e);mobs[i]=e;command(i,"signCast","sign",sign);}phase=11;}
 case 11->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){var p=players.get(i);var type=SignType.values()[sign];check(SignManager.state(p).selected()==type&&SignManager.state(p).concentration()<100,"Selection and payment "+type);switch(type){case IGNI->check(mobs[i].getHealth()<200,"Igni native actual damage");case AARD->check(mobs[i].getHealth()<200&&mobs[i].getZ()>3.5,"Aard actual impulse");case QUEN->check(SignManager.protect(p,w.getDamageSources().fall(),5)==0,"Native Quen pool");case YRDEN->check(mobs[i].hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"Native Yrden slowing");case AXII->check(SignManager.calmed(mobs[i]),"Native Axii suppression");}results.put("sign_"+type+"_"+i,true);mobs[i].discard();command(i,"wait");}sign++;phase=12;}
 case 12->{if(!ack(0)||!ack(1))return;if(SignManager.state(a).concentration()<100||SignManager.state(b).concentration()<100)return;phase=10;}
 case 50->{var saved=new LinkedHashMap<String,Object>();for(int i=0;i<2;i++){saved.put(names[i],SignManager.state(players.get(i)).learned());command(i,"disconnect");}write("signs-resume.json",saved);write("signs-results.json",results);write("resume.json",Map.of("signs",true));phase=51;}
 case 51->{if(!ack(0)||!ack(1))return;s.save(false,true,true);s.stop(false);phase=999;}
 case 100->{for(var e:read("signs-results.json").entrySet())results.put(e.getKey(),e.getValue());check(SignManager.state(a).learned()==31&&SignManager.state(b).learned()==31,"Actual dedicated restart preserves learning");results.put("restart_learning",true);results.put("complete",true);write("complete.json",results);for(int i=0;i<2;i++)command(i,"stop");phase=999;}
 }}catch(Throwable error){try{write("server-failure.json",Map.of("phase",phase,"sign",sign,"error",error.toString()));}catch(Exception ignored){}phase=999;s.stop(false);}});}
}
